const row = $input.first()?.json ?? {};
let state = {};
if (row.state_json) {
  try { state = JSON.parse(row.state_json); }
  catch { throw new Error('Invalid Oura state JSON'); }
}
const isManual = $execution.mode === 'test';
const dueAt = Number(state.nextDueMs ?? 0);
if (!isManual && Number.isFinite(dueAt) && dueAt > Date.now()) return [];
return [{json:{state,isManual}}];

// Prefer plausible producer_timestamp to distinguish new source readings from repeated API responses.
const LOW_AT=5, REARM_AT=15, UNRESPONSIVE_MINUTES=150, MAX_SAMPLE_AGE_MINUTES=360;
const now=Date.now();
const state={...$('Check Next Poll Time').first().json.state};
const rows=$input.first()?.json?.data;
function sourceMs(r) {
  const iso=Date.parse(r.timestamp||'');
  const raw=r.producer_timestamp==null?NaN:Number(r.producer_timestamp);
  const p=Number.isFinite(raw)&&raw>1e12?raw:NaN;
  if(Number.isFinite(p)&&p<=now+300000&&p>Date.parse('2020-01-01T00:00:00Z')&&
     (!Number.isFinite(iso)||Math.abs(p-iso)<=24*3600000)) return p;
  return iso;
}
function interval(level) {
  if(level>40)return 480;
  if(level>30)return 360;
  if(level>20)return 240;
  if(level>10)return 120;
  if(level>7)return 60;
  if(level>5)return 30;
  return 15;
}
state.receipts=Array.isArray(state.receipts)?state.receipts.filter(r=>
  r&&/^[A-Za-z0-9]{30}$/.test(String(r.id))&&Number(r.expiresAtMs)>now):[];
let action='none', alert='none', title='Oura Ring', message='', status='missing';
let level=null, ageMinutes=null, pollMinutes=60, sourceTimeMs=null;
let charging=false, inCharger=false;
if(Array.isArray(rows)&&rows.length){
  const r=rows.reduce((a,b)=>sourceMs(a)>=sourceMs(b)?a:b);
  const l=r.level==null?NaN:Number(r.level);
  const at=sourceMs(r);
  if(Number.isFinite(l)&&l>=0&&l<=100&&Number.isFinite(at)){
    level=l;sourceTimeMs=at;
    ageMinutes=Math.round((now-at)/60000);
    const fresh=ageMinutes>=-5&&ageMinutes<=MAX_SAMPLE_AGE_MINUTES;
    status=fresh?'fresh':'stale';
    charging=r.charging===true;inCharger=r.in_charger===true;
    const onCharger=charging||inCharger, critical=level>0&&level<=LOW_AT;
    pollMinutes=fresh?interval(level):Math.min(60,interval(level));
    if(fresh&&level>=REARM_AT){
      state.lowSent=false;state.unresponsiveSent=false;state.deadSent=false;
      state.sourceTimeMs=null;state.sourceSeenAtMs=null;
    }
    if((onCharger&&fresh)||!critical){
      state.sourceTimeMs=null;state.sourceSeenAtMs=null;
    }else if(fresh&&(state.sourceTimeMs==null||at>Number(state.sourceTimeMs))){
      state.sourceTimeMs=at;state.sourceSeenAtMs=now;
    }
    if(fresh&&(onCharger||level>=REARM_AT)&&state.receipts.length){
      action='cancel';
    }else if(!onCharger){
      if(fresh&&level===0&&state.deadSent!==true){
        action='send';alert='dead';message='Battery dead (0%).';
        state.deadSent=true;state.lowSent=true;
      }else if(fresh&&critical&&state.lowSent!==true){
        action='send';alert='low';message='Battery: '+level+'%. Charge now.';
        state.lowSent=true;
      }else if(critical&&state.lowSent===true&&state.unresponsiveSent!==true&&
        Number.isFinite(Number(state.sourceSeenAtMs))&&Number(state.sourceSeenAtMs)>0&&
        now-Number(state.sourceSeenAtMs)>=UNRESPONSIVE_MINUTES*60000){
        action='send';alert='unresponsive';message='Unresponsive';
        state.unresponsiveSent=true;
      }
    }
  }else status='invalid';
}
state.nextDueMs=now+pollMinutes*60000;
return [{json:{key:'oura',state_json:JSON.stringify(state),action,alert,title,message,
  receiptsToCancel:action==='cancel'?state.receipts.map(r=>r.id):[],
  level,source_time_ms:sourceTimeMs,age_minutes:ageMinutes,status,
  charging,in_charger:inCharger,next_poll_minutes:pollMinutes,
  manual_run:$('Check Next Poll Time').first().json.manual}}];

const rows=$('Evaluate Battery').first().json.receiptsToCancel;
if(!Array.isArray(rows)||!rows.length)throw new Error('Cancel route missing receipt IDs');
return rows.map(receipt=>({json:{receipt}}));

const responses=$input.all();
const expected=$('Prepare Receipt Cancellations').all().length;
if(responses.length!==expected||responses.some(r=>Number(r.json.status)!==1))
  throw new Error('Receipt cancellation incomplete; stored receipts retained.');
const state=JSON.parse($('Evaluate Battery').first().json.state_json);
const canceled=new Set($('Prepare Receipt Cancellations').all().map(r=>r.json.receipt));
state.receipts=(state.receipts||[]).filter(r=>!canceled.has(r.id));
return [{json:{key:'oura',state_json:JSON.stringify(state)}}];

const receipt=$input.first()?.json?.receipt;
if(typeof receipt!=='string'||!/^[A-Za-z0-9]{30}$/.test(receipt))
  throw new Error('Pushover emergency response missing receipt; cannot track cancellation');
const original=$('Evaluate Battery').first().json;
const state=JSON.parse(original.state_json);
state.receipts=Array.isArray(state.receipts)?state.receipts:[];
state.receipts.push({id:receipt,alert:original.alert,expiresAtMs:Date.now()+10800*1000});
return [{json:{key:'oura',state_json:JSON.stringify(state)}}];
